create table user (id text not null primary key, name text not null, email text not null unique, "emailVerified" integer not null, image text, "createdAt" date not null, "updatedAt" date not null);
create table account (id text not null primary key, "accountId" text not null, "providerId" text not null, "userId" text not null references "user" (id) on delete cascade, "accessToken" text, "refreshToken" text, "idToken" text, "accessTokenExpiresAt" date, "refreshTokenExpiresAt" date, scope text, password text, "createdAt" date not null, "updatedAt" date not null);
create table "agentHost" (id text not null primary key, name text, "userId" text references "user" (id) on delete cascade, "defaultCapabilities" text, "publicKey" text, kid text, "jwksUrl" text, "enrollmentTokenHash" text, "enrollmentTokenExpiresAt" date, status text not null, "activatedAt" date, "expiresAt" date, "lastUsedAt" date, "createdAt" date not null, "updatedAt" date not null);
create table agent (id text not null primary key, name text not null, "userId" text references "user" (id) on delete cascade, "hostId" text not null references "agentHost" (id) on delete cascade, status text not null, mode text not null, "publicKey" text not null, kid text, "jwksUrl" text, "lastUsedAt" date, "activatedAt" date, "expiresAt" date, metadata text, "createdAt" date not null, "updatedAt" date not null);
create table "agentCapabilityGrant" (id text not null primary key, "agentId" text not null references "agent" (id) on delete cascade, capability text not null, "deniedBy" text references "user" (id) on delete cascade, "grantedBy" text references "user" (id) on delete cascade, "expiresAt" date, "createdAt" date not null, "updatedAt" date not null, status text not null, reason text, constraints text);
create table "approvalRequest" (id text not null primary key, method text not null, "agentId" text references "agent" (id) on delete cascade, "hostId" text references "agentHost" (id) on delete cascade, "userId" text references "user" (id) on delete cascade, capabilities text, status text not null, "userCodeHash" text, "loginHint" text, "bindingMessage" text, "clientNotificationToken" text, "clientNotificationEndpoint" text, "deliveryMode" text, interval integer not null, "lastPolledAt" date, "expiresAt" date not null, "createdAt" date not null, "updatedAt" date not null);
create table passkey (id text not null primary key, name text, "publicKey" text not null, "userId" text not null references "user" (id) on delete cascade, "credentialID" text not null, counter integer not null, "deviceType" text not null, "backedUp" integer not null, transports text, "createdAt" date, aaguid text);
create table session (id text not null primary key, "expiresAt" date not null, token text not null unique, "createdAt" date not null, "updatedAt" date not null, "ipAddress" text, "userAgent" text, "userId" text not null references "user" (id) on delete cascade);
create table verification (id text not null primary key, identifier text not null, value text not null, "expiresAt" date not null, "createdAt" date not null, "updatedAt" date not null);
create index "account_userId_idx" on account ("userId");
create index "agentHost_enrollmentTokenHash_idx" on "agentHost" ("enrollmentTokenHash");
create index "agentHost_kid_idx" on "agentHost" (kid);
create index "agentHost_status_idx" on "agentHost" (status);
create index "agentHost_userId_idx" on "agentHost" ("userId");
create index "agent_hostId_idx" on agent ("hostId");
create index agent_kid_idx on agent (kid);
create index agent_status_idx on agent (status);
create index "agent_userId_idx" on agent ("userId");
create index "agentCapabilityGrant_agentId_idx" on "agentCapabilityGrant" ("agentId");
create index "agentCapabilityGrant_capability_idx" on "agentCapabilityGrant" (capability);
create index "agentCapabilityGrant_grantedBy_idx" on "agentCapabilityGrant" ("grantedBy");
create index "agentCapabilityGrant_status_idx" on "agentCapabilityGrant" (status);
create index "approvalRequest_agentId_idx" on "approvalRequest" ("agentId");
create index "approvalRequest_hostId_idx" on "approvalRequest" ("hostId");
create index "approvalRequest_status_idx" on "approvalRequest" (status);
create index "approvalRequest_userId_idx" on "approvalRequest" ("userId");
create index "passkey_credentialID_idx" on passkey ("credentialID");
create index "passkey_userId_idx" on passkey ("userId");
create index "session_userId_idx" on session ("userId");
create index verification_identifier_idx on verification (identifier);
